//! 🔢️ Fixed array receiving initializes and retires one actual row while uninitialized native storage has no element callbacks.
use super::*;
use std::mem::MaybeUninit;
pub struct NativeArrayReceiver<I:NativeValueSource+?Sized,T:NativeReceive<dyn NativeValueSource>,const N:usize>where[T;N]:RetireOwned{binding:Option<RetainedCloneBinding>,child:NativeReceiveSlot<dyn NativeValueSource,T>,rows:ManuallyDrop<MaybeUninit<[T;N]>>,pending:ManuallyDrop<Option<T>>,output:ManuallyDrop<Option<[T;N]>>,retirement:RetainedCloneClose,index:usize,live:usize,phase:u8,closing:bool,failed:bool,input:std::marker::PhantomData<fn(&I)>}
impl<I:NativeValueSource+?Sized,T:NativeReceive<dyn NativeValueSource>,const N:usize>NativeArrayReceiver<I,T,N>where[T;N]:RetireOwned{pub fn new()->Self{Self{binding:None,child:Default::default(),rows:ManuallyDrop::new(MaybeUninit::uninit()),pending:ManuallyDrop::new(None),output:ManuallyDrop::new(None),retirement:Default::default(),index:0,live:0,phase:0,closing:false,failed:false,input:std::marker::PhantomData}}fn source<'a>(&self,input:RetainedCloneRef<'a,I>)->Result<RetainedCloneRef<'a,dyn NativeValueSource>,ValueError>{input.get().sequence_child(self.index)?;let index=self.index;Ok(input.project(index,move|v|v.sequence_child(index).expect("validated original array child")))}}
impl<I:NativeValueSource+?Sized,T:NativeReceive<dyn NativeValueSource>,const N:usize>NativeArrayReceiver<I,T,N>where[T;N]:RetireOwned{
 fn place_pending(&mut self,index:usize,g:RetainedCloneGrant)->crate::RetainedWorkOutcome{
  let d=fixed(size_of::<T>());if !retained_clone_grant_admits(g,d){return crate::RetainedWorkOutcome{result:Ok(RetainedCloneStep::Progress(Default::default())),work:0}}
  if self.closing||self.phase!=5||index!=self.index||index!=self.live||index>=N||self.pending.is_none(){return crate::RetainedWorkOutcome{result:Err(invalid()),work:0}}
  let value=match self.pending.take(){Some(v)=>v,None=>return crate::RetainedWorkOutcome{result:Err(ValueError::invariant("pending absent").into()),work:0}};unsafe{self.rows.as_mut_ptr().cast::<T>().add(index).write(value)}self.live+=1;self.index+=1;self.child.begin_close();self.phase=6;crate::RetainedWorkOutcome{result:Ok(RetainedCloneStep::Progress(receipt(d))),work:1}
 }
}

impl<I:NativeValueSource+?Sized,T:NativeReceive<dyn NativeValueSource>,const N:usize>NativeReceive<I>for[T;N]where[T;N]:RetireOwned{type Receiver=NativeArrayReceiver<I,T,N>;fn receiver()->Self::Receiver{NativeArrayReceiver::new()}}
impl<I:NativeValueSource+?Sized,T:NativeReceive<dyn NativeValueSource>,const N:usize>NativeReceiver<I,[T;N]>for NativeArrayReceiver<I,T,N>where[T;N]:RetireOwned{
 fn demands(&self,input:RetainedCloneRef<'_,I>,body:usize)->Result<RetirementDemand,ValueError>{if self.closing{return Err(invalid())}if self.failed{return Ok(Default::default())}if !input.check_binding(&self.binding)?{return Ok(fixed(input.binding_copy_bytes()))}match self.phase{0|1|2|4|7|8=>Ok(fixed(0)),3=>if self.child.ready(){Ok(fixed(0))}else{nested(self.child.demands(self.source(input)?,body)?,0)},5=>Ok(fixed(size_of::<T>())),6=>if self.child.terminal_is_empty(){Ok(fixed(0))}else{self.child.close_demands(body)},_=>Err(invalid())}}
 fn advance(&mut self,input:RetainedCloneRef<'_,I>,control:&mut NativeDecodeControl<'_>,body:usize,g:RetainedCloneGrant)->crate::RetainedWorkOutcome<RetainedCloneStep,crate::OriginalReceivingPrimary>{if self.failed{return crate::RetainedWorkOutcome{result:Err(invalid().into()),work:0}}if self.output_ready(){return crate::RetainedWorkOutcome{result:Ok(RetainedCloneStep::Complete(Default::default())),work:0}}let mut work=0;let result=(||{let d=self.demands(input,body)?;if !retained_clone_grant_admits(g,d){return Ok(RetainedCloneStep::Progress(Default::default()))}control.checkpoint()?;crate::owned::receiving_capacity(control,d.capacity_bytes)?;let turn=input.bind(&mut self.binding,g);work=turn.work;if let Some(p)=turn.result?{control.receive_retained_work(g,crate::RetainedWorkOutcome{result:Ok(RetainedCloneStep::Progress(p)),work:0}).result?;return Ok(RetainedCloneStep::Progress(p))}match self.phase{
 3=>{if self.child.ready(){self.phase=4;work=1;return Ok(RetainedCloneStep::Progress(receipt(fixed(0))))}let turn=self.child.advance(self.source(input)?,control,body,child_grant(g,0));work=turn.work;return turn.result.map(|s|RetainedCloneStep::Progress(s.progress()))},
 4=>{let turn=self.child.take(g);work=turn.work;let Some((value,p))=turn.result?else{return Ok(RetainedCloneStep::Progress(Default::default()))};*self.pending=Some(value);self.phase=5;return Ok(RetainedCloneStep::Progress(p))},
 6 if !self.child.terminal_is_empty()=>{let turn=self.child.close_step(g);work=turn.work;return turn.result.map(|s|RetainedCloneStep::Progress(s.progress())).map_err(Into::into)},_=>{}}
 work=1;match self.phase{0=>self.phase=1,1=>{let length=input.get().sequence_len()?;if length!=N{self.failed=true;return Err(invalid().with_retained_progress(receipt(fixed(0))).into())}self.phase=if N==0{8}else{2};},2=>{input.get().sequence_child(self.index)?;self.phase=3;},5=>{let turn=self.place_pending(self.index,g);work=turn.work;return turn.result.map_err(Into::into)},6=>self.phase=7,7=>{self.child=Default::default();self.phase=if self.index==N{8}else{2};},8=>{if self.live!=N{return Err(invalid().into())}*self.output=Some(unsafe{self.rows.as_ptr().read()});self.live=0;self.phase=9;},_=>return Err(invalid().into())}Ok(if self.output_ready(){RetainedCloneStep::Complete(receipt(fixed(0)))}else{RetainedCloneStep::Progress(receipt(fixed(0)))})})();crate::RetainedWorkOutcome{result,work}}
 fn output_ready(&self)->bool{!self.closing&&self.phase==9&&self.output.is_some()}
 fn take_demand(&self)->Result<RetirementDemand,ValueError>{if !self.output_ready(){return Err(invalid())}Ok(fixed(0))}
 fn take(&mut self,g:RetainedCloneGrant)->crate::RetainedWorkOutcome<Option<([T;N],RetainedCloneProgress)>>{if !self.output_ready()||!retained_clone_grant_admits(g,fixed(0)){return crate::RetainedWorkOutcome{result:Ok(None),work:0}}crate::RetainedWorkOutcome{result:Ok(Some((match self.output.take(){Some(v)=>v,None=>return crate::RetainedWorkOutcome{result:Err(ValueError::invariant("output absent").into()),work:0}},receipt(fixed(0))))),work:1}}
 fn begin_close(&mut self){self.closing=true;self.child.begin_close();}
 fn close_demands(&self,body:usize)->Result<RetirementDemand,ValueError>{if !self.closing{return Err(invalid())}if !self.child.terminal_is_empty(){return self.child.close_demands(body)}if !self.retirement.is_empty(){return self.retirement.demands(body)}if self.pending.is_some(){return self.retirement.next_owner_demands::<T>(true,&None,body)}if self.live>0{return Ok(fixed(0))}if self.output.is_some(){return self.retirement.next_owner_demands::<[T;N]>(true,&None,body)}RetainedCloneBinding::close_demand(&self.binding,body)}
 fn close_step(&mut self,g:RetainedCloneGrant)->crate::RetainedWorkOutcome{if self.terminal_is_empty(){return crate::RetainedWorkOutcome{result:Ok(RetainedCloneStep::Complete(Default::default())),work:0}}let mut work=0;let result=(||{let d=self.close_demands(g.maximum_copy_bytes)?;if !retained_clone_grant_admits(g,d){return Ok(RetainedCloneStep::Progress(Default::default()))}if !self.child.terminal_is_empty(){let turn=self.child.close_step(g);work=turn.work;return turn.result.map(|s|RetainedCloneStep::Progress(s.progress()))}if !self.retirement.is_empty(){let turn=self.retirement.step_granted(g);work=turn.work;return turn.result.map(|s|RetainedCloneStep::Progress(s.progress()))}if self.pending.is_some(){let turn=self.retirement.begin_granted(&mut self.pending,g);work=turn.work;return turn.result.map(|s|RetainedCloneStep::Progress(s.unwrap_or(RetainedCloneStep::Progress(Default::default())).progress()))}if self.live>0{self.live-=1;*self.pending=Some(unsafe{self.rows.as_ptr().cast::<T>().add(self.live).read()});work=1;return Ok(RetainedCloneStep::Progress(receipt(fixed(0))))}if self.output.is_some(){let turn=self.retirement.begin_granted(&mut self.output,g);work=turn.work;return turn.result.map(|s|RetainedCloneStep::Progress(s.unwrap_or(RetainedCloneStep::Progress(Default::default())).progress()))}let turn=RetainedCloneBinding::close_one(&mut self.binding,g);work=turn.work;turn.result})();crate::RetainedWorkOutcome{result,work}}
 fn terminal_is_empty(&self)->bool{self.child.terminal_is_empty()&&self.live==0&&self.pending.is_none()&&self.output.is_none()&&self.retirement.is_empty()&&self.binding.is_none()}
}
impl<I:NativeValueSource+?Sized,T:NativeReceive<dyn NativeValueSource>,const N:usize>Drop for NativeArrayReceiver<I,T,N>where[T;N]:RetireOwned{fn drop(&mut self){let empty=self.terminal_is_empty();assert!(std::thread::panicking()||empty,"native fixed array requires funded closure");if empty{unsafe{ManuallyDrop::drop(&mut self.rows);ManuallyDrop::drop(&mut self.pending);ManuallyDrop::drop(&mut self.output);}}}}

#[cfg(test)]mod tests{
//! 🔢️ The same declared storage rows exercise the actual array initialized prefix instead of a removed Option-array container.
use super::*;
use crate::source_fixture::{Wallet,receive,post_step,denials,close_owned};
#[test]
fn sequence_storage_refusal_retains_the_exact_unpublished_value(){
 let fixture:serde_json::Value=serde_json::from_str(semio_framework_test_fixtures::fixture_text!("../../🌳️value/📖️source/🧪️tests/🧫️fixtures/📐️.json")).unwrap();
 for row in fixture["storage"].as_array().unwrap(){
  let value=row["value"].as_u64().unwrap();let index=row["index"].as_u64().unwrap()as usize;let accepted=row["accepted"].as_bool().unwrap();
  if row["kind"]=="vector"{let mut storage=Vec::with_capacity(row["capacity"].as_u64().unwrap()as usize);let result=<Vec<u64>as NativeSequenceCollection<u64>>::push(&mut storage,index,value);assert_eq!(result.is_ok(),accepted);if !accepted{assert_eq!(result.unwrap_err(),value)}continue}
  assert_eq!(row["capacity"],2);let mut bank=Wallet::from_profile(&fixture["stock"]);let source=crate::source_fixture::capture(DslValue::from(serde_json::json!([3,value])),&mut bank,|w|w.loan(1,4096),|w,p,work,h,g|w.post(p,work,g,h));let mut receiver=NativeArrayReceiver::<DslValue,u64,2>::new();let mut callback=|_|true;let mut control=NativeDecodeControl::new(bank.loan(1,4096).maximum_capacity_bytes,&mut callback);
  for _ in 0..10000{if receiver.phase==5&&receiver.index==1{break}let g=bank.loan(1,4096);let(turn,h)=crate::observe_retirement_allocations(||receive(&mut control,g,bank.work_loan(1),|c|receiver.advance(source.borrow(),c,4096,g)));post_step(&mut bank,turn,g,h,crate::OriginalReceivingPrimary::retained_progress).unwrap();}
  assert_eq!(receiver.phase,5);assert_eq!(receiver.live,1);assert_eq!(receiver.index,1);assert_eq!(*receiver.pending,Some(value));let before=(receiver.live,receiver.index,receiver.rows.as_ptr());let d=fixed(size_of::<u64>());let g=bank.loan(1,4096);
  for denied in denials(g,d){let(turn,h)=crate::observe_retirement_allocations(||receiver.place_pending(index,denied));assert_eq!(turn.work,0);assert_eq!(turn.result.unwrap().progress(),Default::default());assert_eq!(h,(0,0));assert_eq!(*receiver.pending,Some(value));assert_eq!((receiver.live,receiver.index,receiver.rows.as_ptr()),before);}
  let(turn,h)=crate::observe_retirement_allocations(||receiver.place_pending(index,g));let p=match &turn.result{Ok(s)=>s.progress(),Err(e)=>e.retained_progress()};bank.post(p,turn.work,g,h);assert_eq!(turn.result.is_ok(),accepted);
  if accepted{assert_eq!(turn.work,1);assert_eq!(receiver.live,2);assert!(receiver.pending.is_none());let actual=unsafe{std::slice::from_raw_parts(receiver.rows.as_ptr().cast::<u64>(),receiver.live)};assert_eq!(serde_json::to_value(actual).unwrap(),serde_json::json!([3,value]));}else{assert_eq!(turn.work,0);assert_eq!(*receiver.pending,Some(value));assert_eq!((receiver.live,receiver.index,receiver.rows.as_ptr()),before);assert_eq!(row["occupied"].as_bool().unwrap(),index<receiver.live);}
  receiver.begin_close();for _ in 0..10000{if receiver.terminal_is_empty(){break}let g=bank.loan(1,4096);let(turn,h)=crate::observe_retirement_allocations(||receiver.close_step(g));post_step(&mut bank,turn,g,h,ValueError::retained_progress).unwrap();}assert!(receiver.terminal_is_empty());drop(receiver);close_owned(source,&mut bank,4096,10000);
 }
}

}
